// Custom properties the pipeline writes to. Run once per HubSpot account.
const text = (name, label) => ({ name, label, type: 'string', fieldType: 'text' });
const date = (name, label) => ({ name, label, type: 'date', fieldType: 'date' });

const objects = {
  contacts: {
    groupName: 'contactinformation',
    properties: [
      text('birth_place', 'Birth place'),
    ],
  },
  deals: {
    groupName: 'dealinformation',
    properties: [
      text('order_email', 'Order email'),
      text('order_phone', 'Order phone'),
      text('address', 'Address'),
      text('postal_code', 'Postal code'),
      text('city', 'City'),
      text('iban', 'IBAN'),
      text('id_number', 'ID number'),
      date('id_valid_until', 'ID valid until'),
    ],
  },
};

// One item per object type: the HTTP node runs once for each.
return Object.entries(objects).map(([object, { groupName, properties }]) => ({
  json: { object, inputs: properties.map((p) => ({ ...p, groupName })) },
}));
